const apiBase = import.meta.env.VITE_API_URL || 'http://localhost:8787';
async function readCourseProposalDraft() {
  const fields = Array.from(document.querySelectorAll('.wizard-main label'));
  const valueFor = (label) => fields.find((item) => item.textContent.trim().startsWith(label))?.querySelector('input,select,textarea')?.value?.trim() || '';
  const unitName = valueFor('Owning Academic Unit') || 'School of Technology';
  const fallbackUnitIds = {'School of Business & Commerce':'AU-000042','School of Technology':'AU-000057','School of Health Sciences':'AU-000063'};
  let academicUnitId = fallbackUnitIds[unitName] || fallbackUnitIds['School of Technology'];
  try {
    const response = await browserFetch(`${apiBase}/api/academic-structure`);
    const data = response.ok ? await response.json() : null;
    const unit = data?.academicUnits?.find((item) => item.name === unitName);
    if (unit?.id) academicUnitId = unit.id;
  } catch {}
  const courseCode = valueFor('Proposed Course Code') || 'COMP 481';
  const title = valueFor('Official Title') || valueFor('Course Title') || 'Machine Learning';
  const effectiveTerm = valueFor('Proposed Effective Term') || 'Fall 2026';
  return { proposalType: 'New Course', title, academicUnitId, effectiveTerm, details: { courseCode, title, credits: Number(valueFor('Credits')) || 0, academicLevel: valueFor('Academic Level'), courseType: valueFor('Course Type'), description: valueFor('Course Description'), academicRationale: valueFor('Academic Rationale'), source: 'New Course Proposal wizard' } };
}
const browserFetch = window.fetch.bind(window);
const accessToken = () => {
  try {
    return typeof window.__CCMS_GET_ACCESS_TOKEN__ === 'function'
      ? window.__CCMS_GET_ACCESS_TOKEN__()
      : window.__CCMS_ACCESS_TOKEN__;
  } catch { return null; }
};
const fetch = (input, options = {}) => {
  const headers = new Headers(options.headers || {});
  const token = accessToken();
  if (token && !headers.has('Authorization')) headers.set('Authorization', `Bearer ${token}`);
  return browserFetch(typeof input === 'string' ? input.replace('http://localhost:8787', apiBase) : input, { ...options, headers });
};
function useDashboardSnapshot() {
  const [snapshot, setSnapshot] = useState(null);
  useEffect(() => { let active = true; fetch(`${apiBase}/api/dashboard`).then(response => response.ok ? response.json() : null).then(data => { if (active && data) setSnapshot(data); }).catch(() => {}); return () => { active = false; }; }, []);
  return snapshot;
}
function useCatalogueDomain(domain, fallback) {
  const [records, setRecords] = useState(null);
  useEffect(() => { let active = true; fetch(`${apiBase}/api/catalogue`).then(response => response.ok ? response.json() : null).then(data => { if (active) setRecords(data?.catalogue?.[domain]?.records || []); }).catch(() => {}); return () => { active = false; }; }, [domain]);
  const source = records || fallback;
  const normalizers = {
    courses: row => [row.id, row.code, row.title, row.academicUnit, row.status === 'Active' ? row.version.replace('v','') : row.status, row.status],
    programs: row => [row.id, row.title, row.code, row.academicUnit, row.credential, row.status],
    credentials: row => [row.id, row.title, row.code, row.type, row.academicUnit || 'Institutional', row.status, row.type],
    requirements: row => [row.id, row.title, row.ruleType, row.expression, row.status, row.scope],
    outcomes: row => [row.id, row.statement, row.curriculumItem, row.classification, row.mapping, row.status, row.status === 'Complete' ? 'green' : 'risk', row.curriculumItem.includes('Program') ? 'Program Outcomes' : 'Course Outcomes'],
    maps: row => [row.id, row.course, row.program, `${row.outcomes} outcomes · ${row.mappedOutcomes} mapped`, `${row.coverage}%`, row.health, row.health === 'Healthy' ? 'green' : row.health === 'Needs review' ? 'orange' : 'risk']
  };
  return records ? records.map(normalizers[domain] || (row => row)) : source;
}
function useLiveCatalogueTotals(fallback) {
  const [totals, setTotals] = useState(null);
  useEffect(() => { let active = true; fetch(`${apiBase}/api/catalogue`).then(response => response.ok ? response.json() : null).then(data => { if (active && data?.catalogue) setTotals(Object.fromEntries(Object.entries(data.catalogue).map(([key,value]) => [key, value.total]))); }).catch(() => {}); return () => { active = false; }; }, []);
  return totals || fallback;
}
function useConsumerResults() {
  const programs = useCatalogueDomain('programs', [['PRG-000184','Business Administration','BUS-ADM-DIP','School of Business & Commerce','Diploma','Active'],['PRG-000231','Cyber Security','CYBR-ADV-DIP','School of Technology','Advanced Diploma','Active']]);
  const courses = useCatalogueDomain('courses', [['CRS-000481','COMP 481','Machine Learning','School of Technology','3','Active'],['CRS-000392','BUS 210','Financial Accounting','School of Business & Commerce','3','Active']]);
  return [...programs.filter(row => row[5] === 'Active').map(row => [row[0], row[1], row[4], 'Program', row[3], `${row[4]} · ${row[2]}`]), ...courses.filter(row => row[5] === 'Active').map(row => [row[0], `${row[1]} — ${row[2]}`, 'Course', 'Course', row[3], `${row[4]} credits · ${row[5]}`])];
}

