  <div className="dashboard-grid"><section className="panel"><div className="panel-head"><h3>Recent Catalogue Activity</h3><button className="link-btn" onClick={()=>setActive('Curriculum Changes')}>View changes <ChevronRight size={15}/></button></div>{[['CRS-000481','Machine Learning v2.1 published','Jun 18, 2026','green'],['PRG-000267','Digital Marketing · proposed version created','Jun 17, 2026','blue'],['MAP-000392','Business Administration map flagged for review','Jun 16, 2026','orange']].map(x=><div className="review-row" key={x[0]}><div className={`review-dot ${x[3]}`}></div><div><strong>{x[0]}</strong><span>{x[1]}</span></div><em>{x[2]}</em></div>)}</section><section className="panel"><div className="panel-head"><h3>Catalogue Integrity</h3><button className="link-btn" onClick={()=>setActive('Curriculum Health')}>Open health <ChevronRight size={15}/></button></div>{[['Required fields complete','98%','green'],['Outcome mappings reviewed','82%','blue'],['Requirements structured','94%','purple'],['Unresolved conflicts','3','risk']].map(x=><div className="pipeline-row" key={x[0]}><span>{x[0]}</span><div className="pipeline-bar"><i className={x[2]} style={{width:x[1].includes('%')?x[1]:'12%'}}/></div><strong>{x[1]}</strong></div>)}</section></div>
