function Credentials() {
  const [query,setQuery]=useState('');
  const [status,setStatus]=useState('All Statuses');
  const [type,setType]=useState('All Credential Types');
  const credentials=useCatalogueDomain('credentials',[['CRD-000021','Diploma in Business Administration','BUS-ADM-DIP','2 years · 60 credits','School of Business & Commerce','Active','Diploma'],['CRD-000034','Advanced Diploma in Cyber Security','CYBR-ADV-DIP','3 years · 90 credits','School of Technology','Active','Advanced Diploma'],['CRD-000047','Graduate Certificate in Digital Marketing','DMKT-GC','1 year · 30 credits','School of Business & Commerce','Review','Graduate Certificate'],['CRD-000052','Certificate in Health Foundations','HLTH-FND-CERT','1 year · 24 credits','School of Health Sciences','Active','Certificate']])
  const filtered=credentials.filter(credential=>(!query||credential.join(' ').toLowerCase().includes(query.toLowerCase()))&&(status==='All Statuses'||credential[5]===status)&&(type==='All Credential Types'||credential[6]===type));
  return <><AdminHeader title="Credentials" description="Manage governed credential types, award rules, and relationships to academic programs." action="Create Credential Proposal"/><div className="metric-grid admin-metrics"><div className="metric"><div className="metric-icon blue"><ShieldCheck size={20}/></div><div><span>Active Credentials</span><strong>38</strong><small>Official catalogue</small></div></div><div className="metric"><div className="metric-icon green"><CheckCircle2 size={20}/></div><div><span>Programs Linked</span><strong>145</strong><small>Credential pathways</small></div></div><div className="metric"><div className="metric-icon purple"><FileCheck2 size={20}/></div><div><span>Credential Types</span><strong>8</strong><small>Institutional reference data</small></div></div><div className="metric"><div className="metric-icon orange"><Workflow size={20}/></div><div><span>In Review</span><strong>3</strong><small>Proposed changes</small></div></div></div><div className="admin-toolbar"><div className="searchbox"><Search size={16}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search credential name, code, or program..."/></div><button className="outline-btn" onClick={()=>setType(type==='All Credential Types'?'Diploma':type==='Diploma'?'Advanced Diploma':'All Credential Types')}>{type} <ChevronDown size={14}/></button><button className="outline-btn" onClick={()=>setStatus(status==='All Statuses'?'Active':status==='Active'?'Review':'All Statuses')}>{status} <ChevronDown size={14}/></button></div><section className="panel"><div className="panel-head"><div><h3>Credential Catalogue</h3><p className="panel-subtitle">Credential identity, award rules, and program relationships are versioned and auditable.</p></div><span className="record-count">{filtered.length} shown · 38 total</span></div><div className="table"><div className="table-row credential-head"><span>CCMS ID</span><span>Credential</span><span>Code</span><span>Structure</span><span>Academic Unit</span><span>Status</span></div>{filtered.map(credential=><div className="table-row credential-row" key={credential[0]}><span className="ccms-id">{credential[0]}</span><span><strong>{credential[1]}</strong><small>Current version v2.0 · Effective Fall 2026</small></span><span className="ccms-id">{credential[2]}</span><span>{credential[3]}</span><span>{credential[4]}</span><span><em className={`status ${credential[5]==='Active'?'good':'risk'}`}>{credential[5]}</em></span></div>)}</div>{filtered.length===0&&<div className="empty-state">No credentials match the current filters.</div>}</section><div className="info-banner"><ShieldCheck size={18}/><div><strong>Award rules are governed</strong><span>Credential requirements are applied through approved program versions and cannot be changed by publication or external integrations.</span></div></div></>;
}

