  const rows=[['PROP-000184','New Course','COMP 481 — Machine Learning','School of Technology','In Progress','Jun 18, 2026'],['PROP-000176','Program Modification','Digital Marketing Graduate Certificate','School of Business & Commerce','Under Review','Jun 12, 2026'],['PROP-000159','Course Modification','BUS 210 — Financial Accounting','School of Business & Commerce','Returned','May 30, 2026'],['PROP-000143','New Program','Cyber Security Advanced Diploma','School of Technology','Approved','May 15, 2026']];
  const filtered=rows.filter(row=>(!query||row.join(' ').toLowerCase().includes(query.toLowerCase()))&&(tab==='All Proposals'||tab==='Drafts'?tab==='Drafts'?row[4]==='Draft':true:tab==='Returned'?row[4]==='Returned':row[4]==='Under Review'));
  return <><AdminHeader title="My Proposals" description="Track drafts, submissions, reviews, and decisions for curriculum changes." action="Create Proposal"/><div className="metric-grid admin-metrics"><div className="metric"><div className="metric-icon blue"><FileText size={20}/></div><div><span>All Proposals</span><strong>18</strong><small>Created by you</small></div></div><div className="metric"><div className="metric-icon orange"><Workflow size={20}/></div><div><span>In Progress</span><strong>4</strong><small>Continue your work</small></div></div><div className="metric"><div className="metric-icon purple"><ClipboardCheck size={20}/></div><div><span>Under Review</span><strong>7</strong><small>Awaiting decisions</small></div></div><div className="metric"><div className="metric-icon green"><CheckCircle2 size={20}/></div><div><span>Approved</span><strong>7</strong><small>Completed proposals</small></div></div></div><div className="tabs">{['All Proposals','Drafts','Returned','Under Review'].map(name=><button key={name} className={`tab ${tab===name?'active':''}`} onClick={()=>setTab(name)}>{name}</button>)}</div><div className="admin-toolbar"><div className="searchbox"><Search size={16}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search by proposal ID, title, or type..."/></div><button className="outline-btn">All Statuses <ChevronDown size={14}/></button><button className="outline-btn">All Types <ChevronDown size={14}/></button></div><section className="panel"><div className="panel-head"><div><h3>Proposal Workspace</h3><p className="panel-subtitle">Proposals remain separate from Proposed and Official Curriculum Versions.</p></div><span className="record-count">{filtered.length} shown · 18 total</span></div><div className="table"><div className="table-row proposal-head"><span>Proposal ID</span><span>Type</span><span>Curriculum Item</span><span>Academic Unit</span><span>Status</span><span>Updated</span></div>{filtered.map(row=><div className="table-row proposal-row" key={row[0]}><span className="ccms-id">{row[0]}</span><span>{row[1]}</span><span><strong>{row[2]}</strong><small>Proposed Curriculum Version v1.0</small></span><span>{row[3]}</span><span><em className={`status ${row[4]==='Approved'?'good':row[4]==='Returned'?'bad':'risk'}`}>{row[4]}</em></span><span>{row[5]}</span></div>)}</div>{filtered.length===0&&<div className="empty-state">No proposals match this view.</div>}</section></>;
